// merkle — Merkle tree over data blocks
// Hash: sha256

fn leaf_hash::(data) { return @sha256_hex(@bytes("\x00" + data)); }
fn node_hash::(left, right) { return @sha256_hex(@bytes("\x01" + left + right)); }

fn build_tree::(blocks) {
    if (@len(blocks) == 0) { @raise("merkle: empty"); }
    let mut level = [];
    for b in blocks { @push(level, leaf_hash(b)); }
    let mut tree = [level];
    while (@len(level) > 1) {
        let next = [];
        let mut i = 0;
        while (i < @len(level)) {
            if (i + 1 < @len(level)) {
                @push(next, node_hash(level[i], level[i + 1]));
                i += 2;
            } else {
                @push(next, level[i]);
                i += 1;
            }
        }
        level = next;
        @push(tree, level);
    }
    return {"levels": tree, "root": level[0]};
}

fn root_of::(tree) { return tree["root"]; }

fn proof_for::(tree, index) {
    let proof = [];
    let mut idx = index;
    let levels = tree["levels"];
    for level_idx in @range(0, @len(levels) - 1) {
        let level = levels[level_idx];
        let sibling = (idx % 2 == 0) ? idx + 1 : idx - 1;
        if (sibling < @len(level)) {
            @push(proof, {"sibling": level[sibling], "left": idx % 2 == 1});
        }
        idx = @floor(idx / 2);
    }
    return proof;
}

fn verify_proof::(leaf, proof, root) {
    let mut h = leaf_hash(leaf);
    for step in proof {
        if (step["left"]) { h = node_hash(step["sibling"], h); }
        else { h = node_hash(h, step["sibling"]); }
    }
    return h == root;
}

fn version::() { return "1.0.0"; }
